// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address keeper1, address keeper2) public {
        vm.assume(keeper1 != address(0));
        vm.assume(keeper2 != address(0));
        vm.assume(keeper1 != keeper2);

        vm.prank(c.owner());
        c.setKeeper(keeper1);
        assertEq(c.keeper(), keeper1, "initial set failed");

        vm.prank(c.owner());
        c.setKeeper(keeper2);
        assertEq(c.keeper(), keeper2, "keeper not updated to new value");
    }
}
